48	Halfedge_Mesh::VertexRef Halfedge_Mesh::emplace_vertex() {
49		VertexRef vertex;
50		if (free_vertices.empty()) {
51			//allocate a new vertex:
52			vertex = vertices.emplace(vertices.end(), Vertex(next_id++));
53		} else {
54			//recycle vertex from free list:
55			vertex = free_vertices.begin();
56			vertices.splice(vertices.end(), free_vertices, free_vertices.begin());
57			*vertex = Vertex(next_id++); //set to default values
58		}
59		//make sure vertex doesn't reference anything:
60		vertex->halfedge = halfedges.end();
61		return vertex;
62	}
63	
64	Halfedge_Mesh::EdgeRef Halfedge_Mesh::emplace_edge(bool sharp) {
65		EdgeRef edge;
66		if (free_edges.empty()) {
67			//allocate a new edge:
68			edge = edges.emplace(edges.end(), Edge(next_id++, sharp));
69		} else {
70			//recycle edge from free list:
71			edge = free_edges.begin();
72			edges.splice(edges.end(), free_edges, free_edges.begin());
73			*edge = Edge(next_id++, sharp); //set to default values
74		}
75		//make sure edge doesn't reference anything:
76		edge->halfedge = halfedges.end();
77		return edge;
78	}
79	
80	Halfedge_Mesh::FaceRef Halfedge_Mesh::emplace_face(bool boundary) {
81		FaceRef face;
82		if (free_faces.empty()) {
83			//allocate a new face:
84			face = faces.emplace(faces.end(), Face(next_id++, boundary));
85		} else {
86			//recycle face from free list:
87			face = free_faces.begin();
88			faces.splice(faces.end(), free_faces, free_faces.begin());
89			*face = Face(next_id++, boundary); //set to default values
90		}
91		face->halfedge = halfedges.end();
92		return face;
93	}
94	
95	Halfedge_Mesh::HalfedgeRef Halfedge_Mesh::emplace_halfedge() {
96		HalfedgeRef halfedge;
97		if (!free_halfedges.empty()) {
98			//move from free list:
99			halfedge = free_halfedges.begin();
100			halfedges.splice(halfedges.end(), free_halfedges, free_halfedges.begin());
101			*halfedge = Halfedge(next_id++); //set to default values
102		} else {
103			//allocate a new halfedge:
104			halfedge = halfedges.insert(halfedges.end(), Halfedge(next_id++));
105		}
106		//set pointers to default values:
107		halfedge->twin = halfedges.end();
108		halfedge->next = halfedges.end();
109		halfedge->vertex = vertices.end();
110		halfedge->edge = edges.end();
111		halfedge->face = faces.end();
112		return halfedge;
113	}
