116	void Halfedge_Mesh::erase_vertex(VertexRef v) {
117		//clear data:
118		v->id |= 0x80000000u;
119		v->position = Vec3( std::numeric_limits< float >::quiet_NaN(), std::numeric_limits< float >::quiet_NaN(), std::numeric_limits< float >::quiet_NaN() );
120		v->bone_weights.clear();
121	
